MODEL_ID = "qwen/qwen3.6-27b"
UI_BUILD = "V13-REFERENCE-GUI-SCROLL-20260911"
MAX_IMAGES = 3
MAX_IMAGE_BYTES = 8 * 1024 * 1024

DOCTOR_IMAGE = "data:image/png;base64,"


# ------------------------------------------------------------
# HTML helper: remove indentation/newlines before Streamlit sees
# the HTML so it cannot become a Markdown code block.
# ------------------------------------------------------------
def html(markup: str):
    st.markdown("".join(line.strip() for line in markup.splitlines()), unsafe_allow_html=True)


def get_api_key():
    try:
        secret = str(st.secrets.get("GROQ_API_KEY", "")).strip()
        if secret:
            return secret
    except Exception:
        pass
    return os.getenv("GROQ_API_KEY", "").strip()


def image_to_data_url(uploaded_file):
    uploaded_file.seek(0)
    image = Image.open(uploaded_file).convert("RGB")
    longest = max(image.size)

    if longest > 1800:
        scale = 1800 / longest
        image = image.resize(
            (int(image.width * scale), int(image.height * scale)),
            Image.LANCZOS,
        )

    buffer = BytesIO()
    image.save(buffer, format="JPEG", quality=88, optimize=True)
    encoded = base64.b64encode(buffer.getvalue()).decode("utf-8")
    return f"data:image/jpeg;base64,{encoded}"


def safe_list(value):
    if isinstance(value, list):
        return value
    if value in (None, ""):
        return []
    return [str(value)]


def pretty_join(value, fallback="Not reliably available"):
    values = [str(v).strip() for v in safe_list(value) if str(v).strip()]
    return ", ".join(values) if values else fallback


def bullet_html(value, fallback="Nothing reliable was identified."):
    items = [str(v).strip() for v in safe_list(value) if str(v).strip()]
    if not items:
        return f"<p>{fallback}</p>"
    return "<ul>" + "".join(f"<li>{item}</li>" for item in items) + "</ul>"


def analyze_medicine(api_key, uploaded_files):
    client = Groq(api_key=api_key)

    image_parts = []
    for file in uploaded_files[:MAX_IMAGES]:
        image_parts.append(
            {
                "type": "image_url",
                "image_url": {"url": image_to_data_url(file)},
            }
        )

    prompt = """
You are a cautious medicine-package image analysis assistant.

Use visible information from the medicine packaging, blister, bottle, label,
or clearly readable imprint. Never invent missing details.

Rules:
- If the product cannot be identified reliably, mark it uncertain.
- Never identify an unmarked loose pill as certain based only on color or shape.
- Do not diagnose the user.
- Do not prescribe or give patient-specific dose, timing, or duration.
- Doctor-style guidance must remain general, educational, and safety-focused.
- Exact dose, timing, duration, suitability, and interactions must be confirmed
  from the package label, prescription, pharmacist, or doctor.
- Use extra caution for antibiotics, anticoagulants, insulin, steroids,
  sedatives, injections, pediatric medicines, and pregnancy-related products.

Pakistan price rules:
- Express price information only in PKR.
- If a PKR/MRP is clearly visible on the pack, use it and set visible_on_pack.
- Otherwise provide a broad Pakistan retail estimate only when reasonably
  confident and set estimated_not_live.
- If unsure, return "Not reliably available".
- Prices vary by pack size, manufacturer, pharmacy, city, and date.

Alternative brands:
- List them only when the active ingredient is confidently identified.
- Prefer Pakistan-relevant brands when known.
- Do not imply automatic interchangeability.

Return ONLY valid JSON with these keys:
{
  "classification": "medicine | medical_product | not_medicine | uncertain",
  "evidence_status": "clear_label_match | partial_label | insufficient",
  "likely_product_name": "",
  "generic_name_or_active_ingredients": [],
  "strength_visible": "",
  "dosage_form": "",
  "manufacturer_visible": "",
  "visible_text": [],
  "common_uses": [],
  "how_it_is_commonly_used": "",
  "doctor_style_guidance": [],
  "how_to_use_safely": [],
  "important_warnings": [],
  "red_flags": [],
  "verification_steps": [],
  "drug_group": "",
  "alternate_brand_names": [],
  "price_pkr": "",
  "price_basis": "visible_on_pack | estimated_not_live | unavailable",
  "price_note": "",
  "short_summary": ""
}
"""

    result = client.chat.completions.create(
        model=MODEL_ID,
        messages=[
            {
                "role": "user",
                "content": [{"type": "text", "text": prompt}] + image_parts,
            }
        ],
        temperature=0.05,
        top_p=0.85,
        max_completion_tokens=2200,
        response_format={"type": "json_object"},
        stream=False,
    )

    raw = (result.choices[0].message.content or "{}").strip()
    if raw.startswith("```"):
        raw = raw.replace("```json", "", 1).replace("```", "").strip()

    return json.loads(raw)


